-- Phase 7 follow-up (owner, 2026-10-26): an Admin-only per-user "no announcements"
-- flag. A flagged user gets no announcement WhatsApp; the in-app copy (widget +
-- history) stays visible. Self-service opt-out is OPEN. Only the users and
-- announcements tables are touched — no financial or attendance table.
ALTER TABLE "users" ADD COLUMN "announcements_opt_out" BOOLEAN NOT NULL DEFAULT false;

-- Drift fix: ids are generated by the Prisma client (@default(uuid()), as on every
-- other table); the DB-side default added in 20261026170000 is removed.
ALTER TABLE "announcements" ALTER COLUMN "id" DROP DEFAULT;
